import json, math
from pathlib import Path
j=json.loads(Path('/tmp/phase2-combined-report-latest.json').read_text())
low_markers=('gpt-5.4-mini','gpt-5.3-codex','gpt-5.2','claude-sonnet-4-6','claude-haiku-4-5')

def p_lt(c,k,thr=0.05):
    v=c.get(k)
    return isinstance(v,(int,float)) and not math.isnan(v) and v < thr

def improved_metric(c, metric):
    mb=c.get('mean_'+metric+'_baseline')
    mc=c.get('mean_'+metric+'_condition')
    if not isinstance(mb,(int,float)) or not isinstance(mc,(int,float)):
        return False
    return mc < mb

def retained(c):
    delta=c.get('delta') or 0
    sb=c.get('success_rate_baseline') or 0
    sc=c.get('success_rate_condition') or 0
    # clear rejects
    if delta < 0 or sc < sb:
        return False, 'reject'
    if delta > 0 and p_lt(c,'p_value_approx'):
        return True, 'score'
    if delta > 0 and sc > sb:
        return True, 'success lift'
    if delta >= 0 and sc >= sb:
        ops=[]
        for metric,pkey in [('agent_seconds','p_value_agent_seconds'),('total_tokens','p_value_total_tokens'),('cost_usd','p_value_cost_usd'),('turns','p_value_turns')]:
            if improved_metric(c, metric) and p_lt(c,pkey):
                ops.append(metric)
        if ops:
            return True, 'operational:'+','.join(ops)
    return False, 'weak'

rows=[]
for c in j['comparisons']:
    ok,why=retained(c)
    c['_retained']=ok; c['_why']=why
    rows.append(c)

for layer in ['A','B','C']:
    def applies(c):
        if layer=='A': return not c['task_id'].startswith('swe-style-')
        if layer=='B': return c['task_id'].startswith('swe-style-')
        return any(m in c['runner'] for m in low_markers)
    kept=[c for c in rows if applies(c) and c['_retained']]
    rej=[c for c in rows if applies(c) and not c['_retained']]
    print(layer, len(kept), 'retained', len(rej), 'rejected/weak')
    for c in kept:
        print(' ',c['task_id'], c['runner'], c['condition'], f"d={c['delta']:.2f}", f"s={c['success_rate_baseline']:.2f}->{c['success_rate_condition']:.2f}", c['_why'])
    print()
print('Latest suite comparisons:')
for c in rows:
    if c['task_id'] in ('github-cli-repo-name-trims-dotgit','swe-style-github-cli-repo-name-trims-dotgit') and c['runner']!='codex-medium':
        print(c['task_id'], c['runner'], c['condition'], c['n_baseline'], c['n_condition'], f"d={c['delta']:.2f}", f"p={c.get('p_value_approx')}", f"s={c['success_rate_baseline']:.2f}->{c['success_rate_condition']:.2f}", c['_retained'], c['_why'], 'tokens', c.get('mean_total_tokens_baseline'), c.get('mean_total_tokens_condition'), 'pTok', c.get('p_value_total_tokens'), 'sec', c.get('mean_agent_seconds_baseline'), c.get('mean_agent_seconds_condition'), 'pSec', c.get('p_value_agent_seconds'))
